App.register({group:'overview',label:'01 / 指挥台',routes:[{path:'overview/home',title:'工作总览',icon:'◫',permission:'overview',render(){const t=DB.tenants.find(x=>x.id===DB.state.tenant);const ps=DB.projects.filter(p=>p.tenant===DB.state.tenant&&(DB.state.identity!=='employee'||p.owner===DB.identities.find(i=>i.role==='employee').user));const active=ps.filter(p=>p.status==='制作中').length;const taskCards=[];if(DB.state.tenant==='tn-north')taskCards.push(`<div class="callout"><div class="callout-icon">✳</div><div><strong>剧本审核 · 雾城来信</strong><p>AI 已完成剧本与逻辑检查，等待项目负责人确认正式版本。</p><div class="section-gap">${UI.btn('进入审核','go:studio/script-review','btn-sm btn-primary')}</div></div></div>`);if(DB.state.tenant==='tn-lab'&&DB.state.identity!=='employee')taskCards.push(`<div class="callout section-gap" style="background:#fff8f1;border-color:#f4e4d5"><div class="callout-icon" style="background:#f3c99f">!</div><div><strong>生产异常 · 最后一封语音</strong><p>音频模型连续失败，受影响任务已暂停，等待备用策略决策。</p><div class="section-gap">${UI.btn('处理异常','go:pipeline/exceptions','btn-sm')}</div></div></div>`);const tasksHtml=taskCards.length?taskCards.join(''):UI.empty('当前没有待决事项','当前租户范围内没有需要你处理的审核或异常。');return UI.page('CONTROL ROOM / 01','生产指挥台','企业内部生产状态、待决事项与当前租户的工作入口。',(DB.state.identity==='auditor'?'':UI.btn('＋ 新建项目','project:new','btn-lime')),`<div class="hero"><div class="hero-kicker">YOUR PRODUCTION SPACE / ${t.code}</div><h2>让创作想法，成为可交付的作品。</h2><p>AI 接管专业生产环节，你只需要明确创作方向、确认剧本与最终成片。当前工作空间：${t.name}。</p><div class="hero-actions">${DB.state.identity==='auditor'?'':UI.btn('开始一个新项目','project:new','btn-lime')}${UI.btn('查看生产流水线','go:pipeline/board','btn')}</div></div><div class="grid grid-4 section-gap">${UI.metric('当前租户项目',ps.length,'项目归属：'+t.name,'▣')}${UI.metric('正在生产',active,'AI 生产任务执行中','◌')}${UI.metric('待人工决策','2','剧本审核 1 · 异常处置 1','!')}${UI.metric('本月已交付','6','以正式交付记录为统计口径','↗')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-head"><div><div class="card-title">项目生产动态</div><div class="card-sub">当前租户 · 最近更新</div></div><a class="small muted" href="#/workspace/projects">全部项目 →</a></div>${UI.table(['项目 / 编号','进度','当前阶段','状态'],ps.slice(0,4).map(p=>`<tr><td><div class="entity"><div class="entity-mark">${p.title.slice(0,1)}</div><div><div class="entity-name">${p.title}</div><div class="entity-meta mono">${p.id}</div></div></div></td><td><div style="width:85px">${UI.progress(Math.round(p.done/p.episodes*100),'')}</div></td><td>${p.stage}</td><td>${UI.tag(p.status,p.status==='已交付'?'green':p.status.includes('异常')?'red':p.status.includes('审核')?'orange':'blue')}</td></tr>`))}</div><div class="card"><div class="card-head"><div><div class="card-title">需要你确认的事项</div><div class="card-sub">人工参与边界：审核与异常决策</div></div>${UI.tag('2 项待处理','orange')}</div>${tasksHtml}</div></div><div class="grid grid-3 section-gap"><div class="card"><div class="card-title">AI 生产能力状态</div><div class="kpi-line"><span>创意 / 剧本</span>${UI.tag('可用','green')}</div><div class="kpi-line"><span>视觉 / 分镜</span>${UI.tag('可用','green')}</div><div class="kpi-line"><span>视频生成</span>${UI.tag('部分繁忙','orange')}</div><div class="kpi-line"><span>音频 / 后期</span>${UI.tag('可用','green')}</div></div><div class="card"><div class="card-title">本月作品交付趋势</div>${UI.chart([35,52,42,68,61,86,73],['W1','W2','W3','W4','W5','W6','W7'])}<div class="tiny muted section-gap">示意趋势数据 · 以交付作品为统计口径</div></div><div class="card"><div class="card-title">生产纪律</div><p class="small muted" style="line-height:1.8">项目、任务、素材、成本和成片均绑定租户。跨租户查看必须经过授权，员工离职不影响项目资产归属。</p>${UI.btn('查看审计记录','go:platform/audit','btn-sm')}</div></div>`);}}]});
